const keyboard=document.querySelector('omni-keyboard');let session=0;
function openKeyboard(){document.querySelector('#result').textContent='Local typing with private-field protection.';keyboard.show({sessionId:'demo-'+(++session),fieldId:'demo-field',mode:document.querySelector('#mode').value,locale:keyboard.locale||'en',history:['video captions','music theory'],recentURLs:['https://example.com/articles','https://example.org/music'],pasteQueue:[{id:'synthetic-1',label:'Received link',text:'https://example.org/reading',expiresAt:Date.now()+600000}]});}
document.querySelector('#open-keyboard').onclick=openKeyboard;document.querySelector('#mode').onchange=openKeyboard;
keyboard.addEventListener('omnibloom-keyboard-commit',e=>{document.querySelector('#result').textContent='Text committed to the demo field.';});keyboard.addEventListener('omnibloom-keyboard-cancel',()=>document.querySelector('#result').textContent='Typing cancelled.');
window.omniMediaController=window.omniPadController=action=>{if(!keyboard.hidden)return keyboard.handle(action);const controls=[...document.querySelectorAll('#mode,#open-keyboard')];const i=controls.indexOf(document.activeElement);if(['down','right','up','left'].includes(action)){controls[(i+1)%controls.length].focus();return true;}if(action==='cross'||action==='a'){if(document.activeElement?.tagName==='SELECT'){document.activeElement.selectedIndex=(document.activeElement.selectedIndex+1)%4;document.activeElement.dispatchEvent(new Event('change'));}else document.activeElement?.click();return true;}return false;};if(!window.omnibloomHost)openKeyboard();
